<script setup lang="ts">
import { Head, router } from '@inertiajs/vue3';
import { ref } from 'vue';
import {LayoutDashboard, Plus} from 'lucide-vue-next';
import AdminLayout from '@core/Layouts/AdminLayout.vue';
import PageHeader from '@core/Components/PageHeader.vue';
import { Button } from '@/components/ui/button';
import DataTable, { type DataTableColumn } from '@core/Components/DataTable.vue';
import type { FilterDef, Paginator } from '@core/types';
interface Row { id:number; employee_id:string; employee_name?:string; increment_type:string; increment_value:number|string; previous_basic:number|string; new_basic:number|string; previous_gross:number|string; new_gross:number|string; effective_date:string; status:string; reason?:string; decision_comments?:string; requester?:{name?:string}; approver?:{name?:string}; rejector?:{name?:string}; approved_at?:string; rejected_at?:string }
defineProps<{increments:Paginator<Row>;canApprove:boolean}>();
const actionError=ref('');
function showActionErrors(errors:Record<string,string>){actionError.value=Object.values(errors).join(' ')||'The increment decision could not be completed.'}
function approve(id:number){actionError.value='';router.post(route('payroll.increments.approve',id),{},{preserveScroll:true,onError:showActionErrors})}
function reject(id:number){const comments=window.prompt('Optional rejection note:');if(comments===null)return;actionError.value='';router.post(route('payroll.increments.reject',id),{comments},{preserveScroll:true,onError:showActionErrors})}
const columns:DataTableColumn[]=[{key:'employee_id',label:'Employee'},{key:'increment_type',label:'Change'},{key:'previous_basic',label:'Basic salary'},{key:'previous_gross',label:'Gross salary'},{key:'effective_date',label:'Effective'},{key:'reason',label:'Request / decision notes'},{key:'status',label:'Status'},{key:'actions',label:'',align:'right',exportable:false}];
const statusFilters:FilterDef[]=[{key:'status',label:'Status',kind:'select',options:[{value:'pending',label:'Pending'},{value:'applied',label:'Applied'},{value:'rejected',label:'Rejected'}]}];
</script>
<template><AdminLayout :breadcrumbs="[{ title: 'Payroll' }, { title: 'Increments' }]"><Head title="Salary Increments"/><PageHeader title="Salary increments" description="Auditable salary revisions with before/after values, maker-checker approval, effective dates, and recorded decisions." :icon="LayoutDashboard" :actions="[{ label:'Request increment', route:'payroll.increments.create', icon: Plus }]"><p v-if="actionError" role="alert" class="mt-4 rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{{actionError}}</p><DataTable class="mt-5" route-name="payroll.increments.index" title="Salary increments" :columns="columns" :rows="increments.data" :meta="increments.meta" :filter-defs="statusFilters"><template #cell-employee_id="{row}"><strong>{{row.employee_name||row.employee_id}}</strong><span class="block text-xs text-muted-foreground">{{row.employee_id}}</span></template><template #cell-increment_type="{row}">{{row.increment_type==='percentage'?`${row.increment_value}%`:`+${Number(row.increment_value).toLocaleString()}`}}</template><template #cell-previous_basic="{row}">{{Number(row.previous_basic).toLocaleString()}} → {{Number(row.new_basic).toLocaleString()}}</template><template #cell-previous_gross="{row}">{{Number(row.previous_gross).toLocaleString()}} → {{Number(row.new_gross).toLocaleString()}}</template><template #cell-reason="{row}"><details class="max-w-72"><summary class="cursor-pointer truncate text-primary">{{row.reason||'View notes'}}</summary><p class="mt-1 whitespace-pre-wrap text-xs text-muted-foreground">{{row.reason}}</p><p v-if="row.requester?.name" class="mt-2 text-xs text-muted-foreground">Requested by {{row.requester.name}}</p><p v-if="row.decision_comments" class="mt-2 border-t pt-2 text-xs"><strong>Decision:</strong> {{row.decision_comments}}</p><p v-if="row.approver?.name" class="mt-1 text-xs text-muted-foreground">Approved by {{row.approver.name}} · {{row.approved_at}}</p><p v-if="row.rejector?.name" class="mt-1 text-xs text-muted-foreground">Rejected by {{row.rejector.name}} · {{row.rejected_at}}</p></details></template><template #cell-status="{row}"><span class="rounded-full px-2 py-1 text-xs capitalize" :class="row.status==='pending'?'bg-amber-500/10 text-amber-700':row.status==='applied'?'bg-emerald-500/10 text-emerald-700':'bg-muted text-muted-foreground'">{{row.status}}</span></template><template #cell-actions="{row}"><div v-if="row.status==='pending'&&canApprove" class="flex justify-end gap-2"><Button size="sm" variant="outline" @click="reject(Number(row.id))">Reject</Button><Button size="sm" @click="approve(Number(row.id))">Approve</Button></div></template></DataTable>    </PageHeader>
  </AdminLayout></template>
